<section class="card mt-5 overflow-hidden"><div class="border-b border-slate-100 p-5"><h2 class="text-sm font-semibold">Historial de pagos</h2><p class="mt-1 text-[11px] text-slate-400">Consulta consolidada por cliente, préstamo, ruta y cobrador.</p><form class="mt-4 grid gap-2 sm:grid-cols-4"><input type="hidden" name="date" value="{{$date->format('Y-m-d')}}"><select name="client" class="rounded-lg border border-slate-200 px-3 py-2 text-xs"><option value="">Todos los clientes</option>@foreach($stops->pluck('client')->unique('id')->sortBy('full_name') as $client)<option value="{{$client->id}}" @selected(request('client')==$client->id)>{{$client->full_name}}</option>@endforeach</select><select name="route" class="rounded-lg border border-slate-200 px-3 py-2 text-xs"><option value="">Todas las rutas</option>@foreach($routes as $route)<option value="{{$route->id}}" @selected(request('route')==$route->id)>{{$route->name}}</option>@endforeach</select><select name="collector" class="rounded-lg border border-slate-200 px-3 py-2 text-xs"><option value="">Todos los cobradores</option>@foreach($routes->pluck('collector')->unique('id') as $collector)<option value="{{$collector->id}}" @selected(request('collector')==$collector->id)>{{$collector->user->name}}</option>@endforeach</select><button class="rounded-lg bg-[#eeebff] px-4 py-2 text-xs font-semibold text-indigo-600">Filtrar historial</button></form></div><div class="overflow-x-auto"><table class="w-full text-left"><thead class="bg-slate-50 text-[10px] uppercase text-slate-400"><tr><th class="table-cell">Fecha</th><th class="table-cell">Cliente / préstamo</th><th class="table-cell">Préstamo total</th><th class="table-cell">Saldo pendiente</th><th class="table-cell">Pago</th><th class="table-cell">Ruta</th><th class="table-cell">Cobró / registró</th></tr></thead><tbody class="divide-y divide-slate-100">@forelse($paymentHistory as $payment)<tr><td class="table-cell text-xs">{{$payment->recorded_at->format('d/m/Y H:i')}}</td>