<script>document.querySelectorAll('.outcome').forEach(select=>{const form=select.closest('form'),loanSelect=form.querySelector('[name="loan_id"]'),amountInput=form.querySelector('[name="amount"]'),methodSelect=form.querySelector('[name="payment_method"]'),promiseInput=form.querySelector('[name="promise_date"]'),collectedOption=select.querySelector('[value="collected"]'),hasLoan=loanSelect.options.length>1;if(!hasLoan){loanSelect.options[0].textContent='Sin préstamos activos';loanSelect.disabled=true;collectedOption.disabled=true;if(select.value==='collected')select.value='no_payment';const notice=document.createElement('p');notice.className='sm:col-span-2 rounded-lg bg-amber-50 px-3 py-2 text-[11px] text-amber-700';notice.textContent='Este cliente no tiene préstamos activos o en mora. No se puede registrar un abono hasta que exista un préstamo desembolsado.';loanSelect.closest('label').after(notice)}const sync=()=>{const paid=select.value==='collected',promise=select.value==='promise';form.querySelector('.loan-field').classList.toggle('hidden',!paid&&!hasLoan);form.querySelector('.method-field').classList.toggle('hidden',!paid);form.querySelector('.promise-field').classList.toggle('hidden',!promise);form.querySelector('.amount-field').classList.toggle('opacity-60',!paid);loanSelect.required=paid;amountInput.required=paid;amountInput.disabled=!paid;methodSelect.required=paid;promiseInput.required=promise;if(!paid)amountInput.value=''};select.addEventListener('change',sync);sync()});</script>
